+
+  try {
+
+    string srcdir("");
+    if(getenv("SRCDIR") != 0)
+      srcdir = getenv("SRCDIR");
+
+    //
+    // Create a 300x300 white canvas.
+    //
+    Image image( "300x300", "white" );
+
+    //
+    // Draw texture-filled polygon
+    //
