+// Color Implementation
+//
+
+#define MAGICKCORE_IMPLEMENTATION
+#define MAGICK_PLUSPLUS_IMPLEMENTATION 1
+
+#include "Magick++/Include.h"
+#include <string>
+
+using namespace std;
+
+#include "Magick++/Color.h"
