+      _height = geometry_._height;
+      _xOff = geometry_._xOff;
+      _yOff = geometry_._yOff;
+      _xNegative = geometry_._xNegative;
+      _yNegative = geometry_._yNegative;
+      _isValid = geometry_._isValid;
+      _percent = geometry_._percent;
