+    unsigned int  _width;
+    unsigned int  _height;
+    unsigned int  _xOff;
+    unsigned int  _yOff;
+    bool          _xNegative;
+    bool          _yNegative;
+    bool          _isValid;
+    bool          _percent;        // Interpret width & height as percentages (%)
+    bool          _aspect;         // Force exact size (!)
+    bool          _greater;        // Re-size only if larger than geometry (>)
+    bool          _less;           // Re-size only if smaller than geometry (<)
+  };
+} // namespace Magick
